import java.util.*;

class BST {
    private Node root;

    public BST() {
        this.root = null;
    }

    public void add(int value) {
        if (root == null) {
            root = new Node(value);
        } else {
            root.add(value);
        }
    }

    public void preOrder(ArrayList<Integer> list) {
        if (root != null) {
            root.preOrder(list);
        }
    }

    public int countSmallerThan(int n) {
        return countSmallerThan(root, n);
    }

    private int countSmallerThan(Node node, int n) {
        if (node == null) return 0;
        if (node.value < n) {
            return 1 + countSmallerThan(node.left, n) + countSmallerThan(node.right, n);
        } else {
            return countSmallerThan(node.left, n);
        }
    }

