class Solution {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        String entrada = in.nextLine();
        String[] placas = entrada.split(",");

        // Radix Sort (ordenação por dígito, da unidade para a dezena de milhar)
