    private static String[] countingSort(String[] v, int index) {
        int[] count = new int[10];  // Dígitos 0-9
        String[] output = new String[v.length];

        // Contagem de ocorrências
        for (String placa : v) {
            int digit = Character.getNumericValue(placa.charAt(index));
            count[digit]++;
