class HashSet {
    private Integer[] table;
    private int size;

    public HashSet(int size) {
        this.size = size;
        this.table = new Integer[size];
    }

    private int hash(int key) {
        return key % size;
    }

    public void put(int value) {
        int pos = hash(value);
        int originalPos = pos;
        boolean inserted = false;

        // Probing linear para encontrar uma posição livre ou o valor já existente
        while (true) {
            if (table[pos] == null || table[pos] == -1) { // -1 representa "removido" (tombstone)
                table[pos] = value;
                inserted = true;
                break;
            } else if (table[pos] == value) {
                break; // Valor já existe, não precisa inserir novamente
            }
            pos = (pos + 1) % size;
            if (pos == originalPos) {
                break; // Tabela cheia, não insere
            }
        }

        print();
    }

    public void remove(int value) {
        int pos = hash(value);
        int originalPos = pos;

        while (true) {
            if (table[pos] == null) {
                break; // Valor não encontrado
            } else if (table[pos] == value) {
                table[pos] = -1; // Marca como removido (tombstone)
                break;
            }
            pos = (pos + 1) % size;
            if (pos == originalPos) {
                break; // Não encontrado
            }
        }

        print();
    }

    public boolean contains(int value) {
        int pos = hash(value);
