            if (A != B) { // Evita loops duplicados
                undirectedAdj.get(B).add(new Pair(A, W));
            }
        }

        // Imprime grafo direcionado
        System.out.println("Grafo direcionado");
        for (int i = 0; i < N; i++) {
            System.out.print("listaDeAdjacencia[" + i + "] ->");
