class Node<T> {
    private T data;
    private Node<T> right;
    private Node<T> left;

    public Node(T data) {
        this.data = data;
        this.right = null;
        this.left = null;
    }

    public T getData() { return data; }
    public Node<T> getRight() { return right; }
    public Node<T> getLeft() { return left; }
    public void setRight(Node<T> right) { this.right = right; }
    public void setLeft(Node<T> left) { this.left = left; }

    @Override
    public String toString() {
        return data + "," + calculateBalance(this);
    }

    private int calculateBalance(Node<T> node) {
        if (node == null) return 0;
        return height(node.getLeft()) - height(node.getRight());
    }

    private int height(Node<T> node) {
        if (node == null) return -1;
        return 1 + Math.max(height(node.getLeft()), height(node.getRight()));
    }
}

class BST<T extends Comparable<T>> {
    private Node<T> root;

    public BST() {
        this.root = null;
    }

    public void insert(T element) {
        root = insert(root, element);
    }

    private Node<T> insert(Node<T> node, T element) {
        if (node == null) {
            return new Node<>(element);
        }
        if (element.compareTo(node.getData()) < 0) {
            node.setLeft(insert(node.getLeft(), element));
        } else {
            node.setRight(insert(node.getRight(), element));
        }
        return node;
    }

    public Node<T>[] preOrder() {
        int size = size(root);
        Node<T>[] nodes = new Node[size];
        int index = 0;
        preOrder(root, nodes, index);
        return nodes;
    }

    private void preOrder(Node<T> node, Node<T>[] nodes, int index) {
        if (node != null) {
            nodes[index++] = node;
            preOrder(node.getLeft(), nodes, index);
            preOrder(node.getRight(), nodes, index);
        }
    }

    private int size(Node<T> node) {
        if (node == null) return 0;
        return 1 + size(node.getLeft()) + size(node.getRight());
    }
}
