        if (head == null) {
            head = new Node(value);
            tail = head;
        } else if (current.next == null) {
            current.next = new Node(value);
            current.next.prev = current;
            tail = current.next;
        } else {
            addRecursive(value, current.next);
        }
        size++;
    }

