```java
import java.util.Scanner;

class Node {
    int value;
    Node left, right;

    Node(int value) {
        this.value = value;
        this.left = null;
        this.right = null;
    }
}

class BST {
    private Node root;

    public BST() {
        this.root = null;
    }

    public void add(int value) {
        root = add(root, value);
    }

    private Node add(Node node, int value) {
        if (node == null) {
            return new Node(value);
        }
        if (value < node.value) {
            node.left = add(node.left, value);
        } else if (value > node.value) {
            node.right = add(node.right, value);
        }
        return node;
    }

    public int sumLeaves() {
        return sumLeaves(root);
    }

    private int sumLeaves(Node node) {
        if (node == null) {
            return 0;
        }
        if (node.left == null && node.right == null) {
            return node.value; // É uma folha
        }
        return sumLeaves(node.left) + sumLeaves(node.right);
    }
}

public class Solution {
    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        String[] inputs = scan.nextLine().split(" ");

        BST tree = new BST();
        for (String s : inputs) {
            tree.add(Integer.parseInt(s));
        }

        System.out.println(tree.sumLeaves());
    }
}
