import java.util.*;

class BST {
    private Node root;

    public BST() {
        this.root = null;
    }

    public void add(int value) {
        if (root == null) {
            root = new Node(value);
        } else {
            root.add(value);
        }
    }

    public void printMaxPath() {
        if (root == null) {
            throw new RuntimeException("Empty tree");
        }
        StringBuilder path = new StringBuilder();
        Node current = root;
        while (current.right != null) {
            path.append(current.value).append(" ");
            current = current.right;
        }
        path.append(current.value); // Adiciona o último nó (máximo)
        System.out.println(path.toString());
    }

    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        String input = scan.nextLine();
        String[] strArray = input.split(" ");

        BST tree = new BST();
        for (String s : strArray) {
            tree.add(Integer.parseInt(s));
        }

        tree.printMaxPath();
    }
}

class Node {
    int value;
    Node left, right;

    Node(int value) {
        this.value = value;
        this.left = null;
        this.right = null;
    }

    public void add(int value) {
        if (value < this.value) {
            if (left == null) {
                left = new Node(value);
            } else {
                left.add(value);
            }
        } else if (value > this.value) {
            if (right == null) {
                right = new Node(value);
            } else {
                right.add(value);
            }
        }
    }
}
