  private final boolean isDirected;
  private Boolean[] visited;
  private int reachableFromZero;
  private boolean hasCycle;
  private int numberOfEdges;
  public AdjacencyList(int vertices, boolean isDirected) {
    adjacencyList = new ArrayList[vertices];
    this.isDirected = isDirected;
    this.visited = new Boolean[vertices];
    this.hasCycle = false;
    this.reachableFromZero = 0;
    this.numberOfEdges = 0;
    for (int i = 0; i < adjacencyList.length; ++i) {
      adjacencyList[i] = new ArrayList<>();
      visited[i] = false;
    }
  }
  public void addEdge(int startVertex, int endVertex) {
    adjacencyList[startVertex].add(new Edge(startVertex, endVertex, 1));
    if(!isDirected && startVertex != endVertex) adjacencyList[endVertex].add(new Edge(endVertex, startVertex, 1));
    this.numberOfEdges += 1;
  }
  public int getNumberOfVertices() { return adjacencyList.length; }
  public int getNumberOfEdges() { return numberOfEdges; }
  public List<Edge> getEdgesFromVertex(int startVertex) { return new ArrayList(adjacencyList[startVertex]); }
  public void dfs(int node, int par) {
    this.visited[node] = true;
    this.reachableFromZero++;
    for(Edge edge: getEdgesFromVertex(node)) {
      if(!visited[edge.getEndNode()]) dfs(edge.getEndNode(), node);
      else if(edge.getEndNode() != par) { this.hasCycle = true; return; }
    }
  }
